(()=>{const kind=document.body.dataset.game;let muted=localStorage.getItem('arcade-music-muted')==='true',ctx,bus,beat=0,last=0;const bar=document.createElement('div');bar.className='shell-controls';bar.innerHTML='<button id="shell-sound">音樂：開</button><span id="shell-timer" style="font-size:12px;padding:6px;color:#ffe0a1"></span><button id="shell-full">全螢幕 ↗</button><button id="shell-back">遊戲選單</button>';document.body.append(bar);const sound=document.getElementById('shell-sound');const label=()=>sound.textContent=muted?'音樂：關':'音樂：開';label();document.getElementById('shell-back').onclick=()=>{if(parent!==window)parent.postMessage({type:'website-v1-back'},location.origin);else location.href='../../#play'};document.getElementById('shell-full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};sound.onclick=()=>{muted=!muted;localStorage.setItem('arcade-music-muted',String(muted));if(bus)bus.gain.value=muted?0:.16;label()};if(kind==='jet')sound.hidden=true;
function note(freq,dur,vol,type){if(!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);g.connect(bus);o.start();o.stop(t+dur);o.onended=()=>{o.disconnect();g.disconnect()}}
function state(){if(kind==='garden'){try{return {state:gameState.isGameOver?'gameover':gameState.isVictory?'victory':gameState.isPaused?'paused':'playing',score:gameState.score,wave:gameState.wave}}catch{return {state:'start'}}}return window.detailedGameSnapshot?.()||{state:'start'}}
if(kind!=='jet'){const unlock=()=>{if(!ctx){ctx=new AudioContext();bus=ctx.createGain();bus.gain.value=muted?0:.16;bus.connect(ctx.destination)}ctx.resume()};document.addEventListener('pointerdown',unlock);document.addEventListener('keydown',unlock);setInterval(()=>{const s=state();if(!ctx||s.state!=='playing'||muted||document.hidden)return;beat++;const roots=[110,98,87.31,103.83],root=roots[Math.floor(beat/16)%4];if(beat%2===0)note(root,.17,.19,'sawtooth');note(root*[2,3,4,3,2,4,3,2][beat%8],.08,.09,'square');if(beat%4===0)note(55,.1,.4,'sine');if(beat%4===2)note(800,.035,.045,'triangle')},60000/(kind==='runner'?164:144)/2)}
setInterval(()=>{const s=state();document.getElementById('shell-timer').textContent=kind==='garden'?'第 '+(s.wave||1)+'/20 波':Math.max(0,90-Math.floor(kind==='jet'?(s.seconds||0):(s.powers?.time||0)))+'s';if(s.state==='gameover'||s.state==='victory'){if(last!==s.state){const k=kind==='runner'?'coins':kind==='jet'?'shipping':'instalments';try{const a=JSON.parse(localStorage.getItem('website-v1-arcade')||'{}'),r=JSON.parse(localStorage.getItem('website-v1-records')||'{}');a[k]={score:s.score||0,levels:s.wave,completed:s.state==='victory'||kind==='runner'&&(s.powers?.time||0)>=90||kind==='jet'&&(s.seconds||0)>=90};r[k]={best:Math.max(r[k]?.best||0,s.score||0),plays:(r[k]?.plays||0)+1};localStorage.setItem('website-v1-arcade',JSON.stringify(a));localStorage.setItem('website-v1-records',JSON.stringify(r))}catch{}}}last=s.state},500);
window.detailedMusicStatus=()=>({kind,muted,running:ctx?.state==='running',state:state().state});
if(kind==='garden'){window.detailedGameSnapshot=()=>{const s=state();return {...s,sun:gameState.sun,plants:gameState.plants.length,zombies:gameState.zombies.length}};window.addEventListener('load',()=>{togglePause();document.getElementById('pauseMenu').style.display='none';const intro=document.createElement('div');intro.id='garden-intro';intro.innerHTML='<section><small>完整植物防守 · 20 波挑戰</small><h1>守住你嘅花園</h1><p>九種植物・逐波升級嘅敵人<br>先種生產，再安排防線；點陽光收集資源。</p><p>揀上方植物，再撳草地。手機建議橫向。</p><button id="garden-start">開始守護</button></section>';document.body.append(intro);document.getElementById('garden-start').onclick=()=>{intro.remove();resumeGame()}})}
})();
